} else if (*pat == '[') {
    const char *p = pat + 1;
    bool negate = false;
    bool matched = false;
    bool first = true;
    bool closed = false;

    if (*p == '!' || *p == '^') {
        negate = true;
        p++;
    }

    while (*p) {
        if (*p == ']' && !first) {
            closed = true;
            break;
        }
        bool at_first = first;
        first = false;
        if (*p == '\\') {
            p++;
            if (!*p)
                break;
            if (*str == *p)
                matched = true;
            p++;
        } else if (!(at_first && *p == ']') && p[1] == '-' && p[2] != '\0' && p[2] != ']') {
            unsigned char start = (unsigned char)p[0];
            unsigned char end = (unsigned char)p[2];
            unsigned char c = (unsigned char)*str;
            if (c >= start && c <= end)
                matched = true;
            p += 3;
        } else {
            if (*p == *str)
                matched = true;
            p++;
        }
    }

    if (!closed) {
        if (*str != '[')
            return false;
        str++;
        pat++;
        continue;
    }

    if (matched == negate)
        return false;
    if (!*str)
        return false;
    str++;
    pat = p + 1;
}
```
分析：`first` 初始 true，如果 `[` 后第一个字符是 `]`，则 `if (*p == ']' && !first)` 不成立（因为 first true），进入循环体；at_first = first (true)，first=false；然后范围条件 `!(at_first && *p == ']') && ...`，`at_first && *p == ']'` 为 true，所以 `!(true)` 为 false，整个范围条件 false，进入 else 字面量分支，比较 `*p == *str`。p++。所以首字符 `]` 不再被当作范围起始。这解决了第2轮项1。但注意：如果首字符是 `]` 后跟 `-` 等，现在字面量处理。符合 POSIX 首字符 `]` 是字面量。似乎已修。

